entity.extra-imports-model:

import com.axelor.inject.Beans;

import com.educaflow.base.infrastructure.criptografia.DatosCertificado;
import com.educaflow.base.infrastructure.criptografia.TipoCertificado

import com.educaflow.base.infrastructure.pdf.DocumentoPdf;
import com.educaflow.base.infrastructure.pdf.DocumentoPdfFactory;
import com.educaflow.base.infrastructure.pdf.ResultadoFirma;

import com.educaflow.base.util.MetaFileUtil

import java.io.ByteArrayInputStream;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

entity.extra-code-model:

public MetaFilePdf(DocumentoPdf documentoPdf) {
    super();
    try {
        this.setFileName(documentoPdf.getFileName());
        this.setFileType("application/pdf");


        byte[] pdfBytes = documentoPdf.getDatos();
        MetaFileUtil.uploadContent(this, pdfBytes);
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
}

public DocumentoPdf getDocumentoPdf() {
    try {
        byte[] bytes = MetaFileUtil.downloadContent(this);

        DocumentoPdf documentoPdf= DocumentoPdfFactory.getDocumentoPdf(bytes, this.getFileName());

        return documentoPdf;
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
}




public boolean isFirmadoExactamente(String... dnis) {
    if (dnis==null || dnis.length==0) {
        if (this.getNumeroFirmas()==0) {
            return true;
        } else {
            return false;
        }
    }

    if (this.getNumeroFirmas() != dnis.length) {
        return false;
    }

    for (String dni : dnis) {
        if (!isSingleFirmado(dni)) {
            return false;
        }
    }
    return true;
}

private int getNumeroFirmas() {
    DocumentoPdf documentoPdf = this.getDocumentoPdf();
    List<ResultadoFirma> firmas = documentoPdf.getFirmasPdf();
    return firmas.size();
}

private boolean isSingleFirmado(String dni) {
    DocumentoPdf documentoPdf = this.getDocumentoPdf();
    List<ResultadoFirma> firmas = documentoPdf.getFirmasPdf();
    for (ResultadoFirma firma : firmas) {
        if (firma.isCorrecta()) {
            DatosCertificado datosCertificado=firma.getDatosCertificado();
            if (datosCertificado.getTipoCertificado().equals(TipoCertificado.USUARIO_FINAL) || datosCertificado.getTipoCertificado().equals(TipoCertificado.REPRESENTACION)){
                if (datosCertificado.getDNI().equalsIgnoreCase(dni)) {
                    return true;
                }
            }
        }
    }
    return false;
}
